import numpy as np

def inverse(A, tol=1e-12):
    A = np.asarray(A, dtype=float)
    n = A.shape[0]
    M = np.hstack([A.copy(), np.eye(n)])
    for k in range(n):
        p = k + int(np.argmax(np.abs(M[k:, k])))
        if abs(M[p, k]) < tol:
            return None
        if p != k:
            M[[k, p]] = M[[p, k]]
        M[k] /= M[k, k]
        for i in range(n):
            if i != k:
                M[i] -= M[i, k] * M[k]
    return M[:, n:]
